public static Boolean Enqueue(Integer DataValue){
if (TailPointer < 9){
    TailPointer++;
    Queue[TailPointer] = DataValue;
    if(HeadPointer == -1){
          HeadPointer = 0;
    }
    return true;
}else{
    return false;
}
}

