def ReadData(TheToys):
try:
 TheFile = open("Toys.txt")
 for Line in TheFile:
     DataSplit = (Line.strip()).split(",")
     TheToys.append(ToyRecord(DataSplit[0],int(DataSplit[1]), DataSplit[2], DataSplit[3]))
