VB.NET
Function ReadData(TheToys() As ToyRecord)
Dim TempData(3) As String
Dim TempRecord As ToyRecord
Try
 Dim FileReader As New System.IO.StreamReader("Toys.txt")
 While Not FileReader.EndOfStream
      TempData = (FileReader.ReadLine()).Split(",")
      TempRecord.ToyName = TempData(0)
      TempRecord.NumberBricks = TempData(1)
      TempRecord.Difficulty = TempData(2)
      TempRecord.Category = TempData(3)
      TheToys(NumberToys) = TempRecord
