 End While
 FileReader.Close()
Catch ex As Exception
 Console.WriteLine("Cannot open or read from file")
End Try
Return TheToys
End Function
Java
public static ToyRecord[] ReadData(ToyRecord[] TheToys){
String[] TempData;
try{
Scanner Scanner1 = new Scanner(new File("Toys.txt"));
while(Scanner1.hasNextLine()){
  TempData = Scanner1.nextLine().split(",");
  TheToys[NumberToys] = new ToyRecord(TempData[0],Integer.parseInt(TempData[1]),TempData[2],TempData[3]);
  NumberToys++;
}
Scanner1.close();
} catch(FileNotFoundException ex){
System.out.println("No file found");
}
return TheToys;
}

