Example program code
Python
def SearchToys(TheToys):
SelectedToys = []
Difficulty = -1
while Difficulty < 1 or Difficulty > 3:
     Difficulty = int(input("Enter 1 for easy, 2 for medium and 3 for expert "))
if Difficulty == 1:
     Choice = "Easy"
elif Difficulty == 2:
     Choice = "Medium"
else:
  Choice = "Expert"
for Item in TheToys:
      if Item.Difficulty == Choice:
           SelectedToys.append(Item)
return SelectedToys
VB.NET
Function SearchToys(TheToys)
Dim SelectedToys(16) As ToyRecord
Dim Difficulty As Integer = -1
Dim Choice As String
NumberSelected = 0
While (Difficulty < 1 Or Difficulty > 3)
   Console.WriteLine("Enter 1 for easy, 2 for medium and 3 for expert ")
   Difficulty = Console.ReadLine()
End While
If Difficulty = 1 Then
   Choice = "Easy"
ElseIf Difficulty = 2 Then
   Choice = "Medium"
Else
   Choice = "Expert"
End If
For x = 0 To NumberToys - 1
   If TheToys(x).Difficulty = Choice Then
        SelectedToys(NumberSelected) = TheToys(x)
        NumberSelected = NumberSelected + 1
   End If
Next
Return SelectedToys
End Function
Java
public static ToyRecord[] SearchToys(ToyRecord[] TheToys){
   ToyRecord[] SelectedToys = new ToyRecord[16];
   Integer Difficulty = -1;
   String Choice = "";
   NumberSelected = 0;
   Scanner Scanner1 = new Scanner(System.in);
   while(Difficulty < 1 || Difficulty > 3){
        System.out.println("Enter 1 for easy, 2 for medium and 3 for expert ");
       try{
                Difficulty = Integer.parseInt(Scanner1.nextLine());
       }catch(NumberFormatException ex){}
   }
   if(Difficulty == 1){
        Choice = "Easy";
   }else if(Difficulty == 2){
        Choice = "Medium";
   }else{
        Choice = "Expert";
   }
   for(Integer x = 0; x < NumberToys; x++){
        if((TheToys[x].Difficulty).equals(Choice)){
           SelectedToys[NumberSelected] = TheToys[x];
          NumberSelected++;
       }
    }
    return SelectedToys;
}

